style.css:
@-moz-document domain("discord.com") {
:root {
    color-scheme: dark !important;
    --steam-bg: #071426;
    --steam-panel: #10243b;
    --steam-card: #172e47;
    --steam-blue: #1a9fff;
    --steam-glow: #00baff;
    --steam-text: #e6f1ff;
  }

  body,
  #app-mount {
    background: var(--steam-bg) !important;
    color: var(--steam-text) !important;
  }

  #app-mount [class*="sidebar"] {
    background: #091a2d !important;
  }

  #app-mount [class*="chat"] {
    background: #0b1b30 !important;
  }

  #app-mount [class*="container"] {
    border-color: #16436b !important;
  }

  #app-mount [class*="message"] {
    color: var(--steam-text) !important;
  }

  #app-mount [class*="channel"]:hover,
  #app-mount [class*="interactive"]:hover {
    background: #12395b !important;
  }

  #app-mount button {
    border-radius: 8px !important;
    transition: 0.2s ease !important;
  }

  #app-mount button:hover {
    box-shadow: 0 0 12px #00baff66 !important;
  }

  #app-mount textarea,
  #app-mount input {
    background: #08182a !important;
    color: white !important;
    border: 1px solid var(--steam-blue) !important;
    border-radius: 10px !important;
  }

  ::selection {
    background: #087dce !important;
    color: white !important;
  }

  * {
    scrollbar-color: #168de0 #071426 !important;
  }
}
